        uint32_t getNumOutputEvents (EndpointHandle endpointHandle)
        {
            if (endpointHandle == 76) return (uint32_t) cmajState.status_eventCount;
            if (endpointHandle == 77) return (uint32_t) cmajState.childInfo_eventCount;
            if (endpointHandle == 78) return (uint32_t) cmajState.telemetry_eventCount;
            if (endpointHandle == 79) return (uint32_t) cmajState.rxAck_eventCount;
            if (endpointHandle == 80) return (uint32_t) cmajState.mtsInfo_eventCount;
            throw std::runtime_error ("Unknown event endpointHandle:" + std::to_string (endpointHandle));
            return {};
        }

        void resetOutputEventCount (EndpointHandle endpointHandle)
        {
            if (endpointHandle == 76) { cmajState.status_eventCount = 0; return; }
            if (endpointHandle == 77) { cmajState.childInfo_eventCount = 0; return; }
            if (endpointHandle == 78) { cmajState.telemetry_eventCount = 0; return; }
            if (endpointHandle == 79) { cmajState.rxAck_eventCount = 0; return; }
            if (endpointHandle == 80) { cmajState.mtsInfo_eventCount = 0; return; }
        }

        uint32_t getOutputEventType (EndpointHandle endpointHandle, uint32_t index)
        {
            if (endpointHandle == 76) return (uint32_t) cmajState.status[(IndexType) index].type;
            if (endpointHandle == 77) return (uint32_t) cmajState.childInfo[(IndexType) index].type;
            if (endpointHandle == 78) return (uint32_t) cmajState.telemetry[(IndexType) index].type;
            if (endpointHandle == 79) return (uint32_t) cmajState.rxAck[(IndexType) index].type;
            if (endpointHandle == 80) return (uint32_t) cmajState.mtsInfo[(IndexType) index].type;
            throw std::runtime_error ("Unknown event endpointHandle:" + std::to_string (endpointHandle));
            return {};
        }

        static uint32_t getOutputEventDataSize (EndpointHandle endpointHandle, uint32_t typeIndex)
        {
            (void) endpointHandle; (void) typeIndex;

            if (endpointHandle == 76 && typeIndex == 0) return 384;
            if (endpointHandle == 77 && typeIndex == 0) return 704;
            if (endpointHandle == 78 && typeIndex == 0) return 160;
            if (endpointHandle == 79 && typeIndex == 0) return 4;
            if (endpointHandle == 80 && typeIndex == 0) return 720;
            throw std::runtime_error ("Unknown event endpointHandle:" + std::to_string (endpointHandle));
            return 0;
        }

        uint32_t readOutputEvent (EndpointHandle endpointHandle, uint32_t index, unsigned char* dest)
        {
            if (endpointHandle == 76)
            {
                auto& event = cmajState.status[(IndexType) index];
                if (event.type == 0)
                {
                    memcpy (dest, std::addressof (event.value_0), 384);
                    dest += 384;
                    return (uint32_t) event.frame;
                }
            }
            if (endpointHandle == 77)
            {
                auto& event = cmajState.childInfo[(IndexType) index];
                if (event.type == 0)
                {
                    memcpy (dest, std::addressof (event.value_0), 704);
                    dest += 704;
                    return (uint32_t) event.frame;
                }
            }
            if (endpointHandle == 78)
            {
                auto& event = cmajState.telemetry[(IndexType) index];
                if (event.type == 0)
                {
                    memcpy (dest, std::addressof (event.value_0), 160);
                    dest += 160;
                    return (uint32_t) event.frame;
                }
            }
            if (endpointHandle == 79)
            {
                auto& event = cmajState.rxAck[(IndexType) index];
                if (event.type == 0)
                {
                    memcpy (dest, std::addressof (event.value_0), 4);
                    dest += 4;
                    return (uint32_t) event.frame;
                }
            }
            if (endpointHandle == 80)
            {
                auto& event = cmajState.mtsInfo[(IndexType) index];
                if (event.type == 0)
                {
                    memcpy (dest, std::addressof (event.value_0), 720);
                    dest += 720;
                    return (uint32_t) event.frame;
                }
            }

            throw std::runtime_error ("Unknown event endpointHandle:" + std::to_string (endpointHandle));
            return {};
        }

